import{_ as n,a as t}from"./chunks/printer-bars.CnFg_LrS.js";import{_ as r,o as i,c as a,a3 as s}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Printer – Drucker und Patronen","description":"Eigenständiges Drucker-Widgetset mit Status und bis zu sechs automatisch gleichmäßig verteilten Patronen.","frontmatter":{"title":"Printer – Drucker und Patronen","description":"Eigenständiges Drucker-Widgetset mit Status und bis zu sechs automatisch gleichmäßig verteilten Patronen."},"headers":[],"relativePath":"projects/grafik-visual-studio/printer.md","filePath":"projects/grafik-visual-studio/printer.md","lastUpdated":1793127012000}'),o={name:"projects/grafik-visual-studio/printer.md"};function d(l,e,u,g,h,c){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="printer" tabindex="-1">Printer <a class="header-anchor" href="#printer" aria-label="Permalink to &quot;Printer&quot;">​</a></h1><p>Ab <strong>Studio 0.1.273</strong> heißt die Auswahl <strong>Eigenschaften → WIDGET → Patronen → Stil → Patronen / Balken</strong>. <strong>Patronen</strong> zeigt die bisherigen Grafiken nebeneinander; <strong>Balken</strong> zeigt 1–6 Zeilen mit Name, horizontalem Füllstand und Prozentwert. Entitäten, Farben und Warnschwelle gelten für beide Stile. Fehlende Werte erscheinen als <strong>—</strong>; die frühere Toner-Auswahl wird als Balken übernommen. Die volle/halbe Patronengröße gilt nur für die Patronengrafiken. <strong>Printer-Paket 0.1.1</strong> enthält die korrigierte Auswahl; vorhandene 0.1.0-Pakete werden vom aktualisierten Studio ebenfalls unterstützt.</p><p><strong>Printer 0.1.1</strong> ist ein eigenes externes Widgetset von <strong>rockbaer2007</strong>. Für die hier gezeigte Stilauswahl wird <strong>Grafik Visual Studio 0.1.273 oder neuer</strong> benötigt. Es zeigt einen Drucker mit aktuellem Status und <strong>1–6 Tinten- oder Tonerfüllständen</strong>, wahlweise als Patronengrafiken oder horizontale Balken.</p><h3 id="stil-patronen" tabindex="-1">Stil: Patronen <a class="header-anchor" href="#stil-patronen" aria-label="Permalink to &quot;Stil: Patronen&quot;">​</a></h3><p>Das Bild zeigt die Runtime mit Testdaten.</p><p><img src="'+n+'" alt="Printer mit sechs Patronen und Warnmarkierung"></p><h3 id="stil-balken" tabindex="-1">Stil: Balken <a class="header-anchor" href="#stil-balken" aria-label="Permalink to &quot;Stil: Balken&quot;">​</a></h3><p>Unter <strong>Eigenschaften → WIDGET → Patronen → Stil</strong> die Option <strong>Balken</strong> wählen. Das folgende Runtime-Bild zeigt sechs Füllstände mit Testdaten: <strong>Gelb 18 %</strong> liegt unter der Warnschwelle von 20 % und wird markiert. Für <strong>Grau</strong> fehlt ein Messwert; der Balken ist schraffiert und zeigt <strong>—</strong> statt eines erfundenen Prozentwerts.</p><p><img src="'+t+'" alt="Printer im Balkenstil mit sechs Füllständen, Warnung bei Gelb und unbekanntem Graufüllstand"></p><h2 id="originalprojekt" tabindex="-1">Originalprojekt <a class="header-anchor" href="#originalprojekt" aria-label="Permalink to &quot;Originalprojekt&quot;">​</a></h2><p>Vorbild ist <a href="https://github.com/ADNPolymerase/ha-printer-card" target="_blank" rel="noreferrer">HA Printer Card von ADNPolymerase</a>, veröffentlicht unter der <a href="https://github.com/ADNPolymerase/ha-printer-card/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT-Lizenz</a>. Das Original ist eine Lovelace-Karte. Printer verwendet eine eigene SVG-Zeichnung, einen eigenen Studio-Renderer und ausdrücklich gewählte Home-Assistant-Entitäten. Originalcode und Originalgrafiken sind nicht eingebunden. Es gehört zu einem eigenen Set in der Palette und nicht zu Industrial.</p><h2 id="installieren" tabindex="-1">Installieren <a class="header-anchor" href="#installieren" aria-label="Permalink to &quot;Installieren&quot;">​</a></h2><ol><li>Grafik Visual Studio auf <strong>0.1.273 oder neuer</strong> aktualisieren.</li><li><a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/ha_grafik_visual_studio/packages/printer/ugso.printer.wg" target="_blank" rel="noreferrer">ugso.printer.wg herunterladen</a>.</li><li>Unter <strong>Einstellungen → Widget-Pakete → Lokal</strong> installieren.</li><li><strong>Printer → Drucker</strong> aus der Palette einfügen und die Status- sowie Füllstandsentitäten mit <strong>…</strong> auswählen.</li></ol><p>Das Paket enthält eine deklarative Widgetdefinition, ein eigenes Palettensymbol, Anleitung und MIT-Lizenz. Ausführbarer Paketcode ist nicht enthalten. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/printer" target="_blank" rel="noreferrer">Quellcode und Paket-Anleitung</a>.</p><h2 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h2><p>Ab Studio <strong>0.1.270</strong> stehen unter <strong>Eigenschaften → WIDGET</strong> auch <strong>CSS Font &amp; Text</strong>, <strong>CSS Hintergrund</strong>, <strong>CSS Ränder</strong> und <strong>CSS Schatten und Abstand</strong> bereit, zusätzlich zu <strong>CSS Allgemein</strong>. Die neuen Gruppen sind zunächst ausgeschaltet. Über ihren Haken einschalten und Schrift, Hintergrund/Bild, Rahmenfarbe/-breite/-stil, einen Radius für alle Ecken (<strong>0 = eckig</strong>), Schatten und Abstände festlegen. CSS wirkt auf die sichtbare Druckerkarte statt hinter deren Hintergrund. Status- und Patronenfarben behalten ihre eigenen Einstellungen. Bestehendes Paket weiterverwenden.</p><table tabindex="0"><thead><tr><th>Bereich</th><th>Einstellung</th></tr></thead><tbody><tr><td>Drucker</td><td>Bezeichnung, Statusentität, Modell <code>mfp</code> (Multifunktion), <code>inkjet</code> (Tintenstrahl) oder <code>office</code> (Bürodrucker).</td></tr><tr><td>Patronen</td><td>Anzahl <strong>1–6</strong>, <strong>Stil → Patronen / Balken</strong>, Warnschwelle <strong>0–100 %</strong>, Standard <strong>20 %</strong>.</td></tr><tr><td>Patrone 1–6</td><td>Eigene Füllstandsentität in Prozent, Beschriftung und Farbe. Die ersten N Einträge sind aktiv. Spätere Bindungen bleiben gespeichert und werden erst bei erhöhter Anzahl wieder abgefragt.</td></tr><tr><td>Statusmeldung</td><td>Ausblendbar. Optionale separate Entität, sonst <code>state_message</code> bzw. <code>state_reason</code> der Druckerentität.</td></tr><tr><td>Zusatzwerte</td><td>Optionale Entitäten für Leistung und Seitenzähler.</td></tr><tr><td>Farben und Größe</td><td>Hintergrund-, Schrift- und Druckstatusfarbe. Standard <strong>480 × 440 px</strong>, Mindestgröße <strong>240 × 280 px</strong>.</td></tr></tbody></table><p>Die Anzahl bestimmt die Verteilung; es sind keine manuellen X-Positionen je Patrone nötig. Bei knappem Platz werden lange Namen gekürzt. Vollständige Namen und Werte stehen im Tooltip. Ab <strong>Studio 0.1.263</strong> erscheinen nur die gewählten Patronen in den Eigenschaften: bei 4 die Gruppen <strong>Patrone 1–4</strong>, bei 5 <strong>Patrone 1–5</strong>. Einstellungen ausgeblendeter Patronen bleiben gespeichert und erscheinen wieder, wenn die Anzahl erhöht wird.</p><h2 id="eigenes-druckerfoto-und-patronengroße" tabindex="-1">Eigenes Druckerfoto und Patronengröße <a class="header-anchor" href="#eigenes-druckerfoto-und-patronengroße" aria-label="Permalink to &quot;Eigenes Druckerfoto und Patronengröße&quot;">​</a></h2><p>Ab <strong>Studio 0.1.262</strong> stehen unter <strong>Druckermodell und Bild</strong> zusätzlich eine freie Modellbezeichnung, die Auswahl <strong>Standardgrafik / Eigenes Bild</strong> und <strong>Foto Ihres Druckers (URL oder /local/... Pfad)</strong> bereit. Das Eintragen eines Bildpfads aktiviert das eigene Foto automatisch; auch Bild-URLs ohne Dateiendung werden unterstützt. Alternativ lädt <strong>Bild hochladen</strong> eine PNG-, JPEG-, WebP-, GIF- oder SVG-Datei bis 2 MB direkt ins Projekt. Hochgeladene Bilder sind im gespeicherten Projekt enthalten. Bei URLs und <code>/local/...</code>-Pfaden muss die Bildquelle auch in der Runtime erreichbar sein.</p><p>Das Foto wird proportional eingepasst. Bei fehlendem Bild oder Ladefehler erscheint die Standardgrafik. Status und Patronen bleiben unabhängig vom Foto aktiv; die Blattanimation gehört zur Standardgrafik. <strong>Patronengröße</strong> bietet <strong>Volle Größe / Halbe Größe</strong>, mit <strong>Halbe Größe</strong> als Vorgabe. Nur die Grafiken werden verkleinert, Beschriftungen und Prozentwerte behalten ihre Größe. Diese Einstellungen erscheinen auch bei bereits installiertem Printer-Paket; eine Neuinstallation des Pakets ist nicht nötig.</p><h2 id="status-und-messwerte" tabindex="-1">Status und Messwerte <a class="header-anchor" href="#status-und-messwerte" aria-label="Permalink to &quot;Status und Messwerte&quot;">​</a></h2><p>Die Sprache folgt automatisch der Studio-Einstellung <strong>DE/EN</strong>, einschließlich automatischer Übernahme aus Home Assistant. Eine separate Widget-Sprachauswahl gibt es nicht. Status, Hinweise und Eigenschaften werden übersetzt; eigene Beschriftungen, Modellnamen und Meldungen der Entität bleiben unverändert.</p><p>Bereit, Drucken, Ruhezustand, Hinweis, Gestoppt, Offline und unbekannt werden aus gängigen Statuswerten erkannt. Beim Drucken bewegt sich ein Blatt und die LED blinkt. Die Browseroption für reduzierte Bewegung schaltet diese Animationen ab. Fehler und Papierstau haben Vorrang; eine reine Füllstandswarnung beendet die Druckanimation nicht.</p><p>Editor und Runtime lesen dieselben aktuellen Home-Assistant-Werte. Fehlende oder ungültige Füllstände erscheinen als <strong>—</strong>, nicht als 0 %. Gültige Zahlen werden auf <strong>0–100 %</strong> begrenzt. Bei Werten kleiner oder gleich der Warnschwelle werden die betreffende Patrone und ihr Wert markiert; darunter erscheinen die betroffenen Namen.</p><h2 id="weboberflache" tabindex="-1">Weboberfläche <a class="header-anchor" href="#weboberflache" aria-label="Permalink to &quot;Weboberfläche&quot;">​</a></h2><p><strong>URL der Weboberfläche (auto = vom Drucker)</strong> blendet einen <strong>Web ↗</strong>-Link ein. Eine manuell eingetragene URL hat Vorrang. <code>auto</code> verwendet die erste HTTP-/HTTPS-Adresse aus <code>configuration_url</code>, <code>web_url</code>, <code>url</code>, <code>device_url</code> oder <code>printer_uri</code> der Statusentität. Fehlt eine solche Adresse, bleibt der Link verborgen; es erfolgt keine Gerätesuche. Ein leeres Feld blendet ihn ebenfalls aus. Die Weboberfläche öffnet sich in einem neuen Tab.</p><h2 id="umfang-dieser-version" tabindex="-1">Umfang dieser Version <a class="header-anchor" href="#umfang-dieser-version" aria-label="Permalink to &quot;Umfang dieser Version&quot;">​</a></h2><p>Diese erste Version verwendet ausdrücklich ausgewählte Entitäten. Sie bietet keine automatische Geräte-/Patronensuche, Verschleißteile, Steckdosensteuerung oder Testdruck. Alle Anbindungen sind lesend. Die separat nutzbare Originalkarte bietet weitere Funktionen.</p>',29)])])}const p=r(o,[["render",d]]);export{f as __pageData,p as default};
